import BaseService from "./BaseService.js";
//#region packages/editor/src/sdk/services/ComponentList.ts
var ComponentList = class extends BaseService {
	state;
	constructor(ctx) {
		super([]);
		this.state = ctx.reactivity.shallowReactive({ list: [] });
	}
	/**
	* @param componentGroupList 组件列表配置
	*/
	setList(componentGroupList) {
		this.state.list = componentGroupList;
	}
	getList() {
		return this.state.list;
	}
	resetState() {
		this.state.list = [];
	}
	destroy() {
		this.resetState();
		this.removeAllListeners();
		this.removeAllPlugins();
	}
};
//#endregion
export { ComponentList as default };
