import { isIncludeDataSource } from "../../utils/editor.js";
import { isValueIncludeDataSource } from "@tmagic/utils";
import { DepTargetType, NODE_CONDS_KEY, NodeType, createCodeBlockTarget, createDataSourceCondTarget, createDataSourceMethodTarget, createDataSourceTarget } from "@tmagic/core";
//#region packages/editor/src/sdk/utils/dep.ts
/** 数据源依赖类型 -> 写回 root 的字段 */
var DEPS_KEY = {
	[DepTargetType.DATA_SOURCE]: "dataSourceDeps",
	[DepTargetType.DATA_SOURCE_COND]: "dataSourceCondDeps",
	[DepTargetType.DATA_SOURCE_METHOD]: "dataSourceMethodDeps"
};
var DATA_SOURCE_DEP_TYPES = [
	DepTargetType.DATA_SOURCE,
	DepTargetType.DATA_SOURCE_COND,
	DepTargetType.DATA_SOURCE_METHOD
];
var DATA_SOURCE_TARGET_CREATORS = {
	[DepTargetType.DATA_SOURCE]: createDataSourceTarget,
	[DepTargetType.DATA_SOURCE_COND]: createDataSourceCondTarget,
	[DepTargetType.DATA_SOURCE_METHOD]: createDataSourceMethodTarget
};
var isDataSourceDepType = (type) => type in DEPS_KEY;
/** 显示条件（`NODE_CONDS_KEY`）相关的字段 */
var isCondsPath = (propPath) => new RegExp(`${NODE_CONDS_KEY}.(\\d)+.cond`).test(propPath) || new RegExp(`${NODE_CONDS_KEY}.(\\d)+.cond.(\\d)+.value`).test(propPath) || propPath === NODE_CONDS_KEY;
/**
* 判断一批已更新的节点哪些需要重新收集数据源依赖。
*
* - 根节点、数据源相关的字段变化、修改的 key 已经在收集到的依赖中：需要重新收集
* - 其余只需要收集代码块、数据源方法依赖
*/
var classifyUpdatedNodes = (ctx, data) => {
	const needRecollectNodes = [];
	const normalNodes = [];
	const needRecollect = ({ newNode, oldNode, changeRecords }) => {
		if (!changeRecords?.length) return isIncludeDataSource(newNode, oldNode);
		const dataSourceTargets = Object.values(ctx.dep.getTargets(DepTargetType.DATA_SOURCE) || {});
		return changeRecords.some(({ propPath, value }) => {
			if (!propPath || isCondsPath(propPath) || isValueIncludeDataSource(value)) return true;
			return dataSourceTargets.some((target) => target.deps[newNode.id]?.keys.includes(propPath));
		});
	};
	for (const item of data) (item.newNode.type !== NodeType.ROOT && needRecollect(item) ? needRecollectNodes : normalNodes).push(item.newNode);
	return {
		needRecollectNodes,
		normalNodes
	};
};
/** 数据源变化规则：命中的 propPath 需要重建并重新收集哪些依赖 */
var DATA_SOURCE_RECOLLECT_RULES = [
	{
		types: [DepTargetType.DATA_SOURCE, DepTargetType.DATA_SOURCE_COND],
		test: (path) => path === "fields" || /fields.(\d)+.name/.test(path) || /fields.(\d)+.defaultValue/.test(path) || /fields.(\d)+$/.test(path)
	},
	{
		types: [DepTargetType.DATA_SOURCE],
		test: (path) => path === "mocks"
	},
	{
		types: [DepTargetType.DATA_SOURCE_METHOD],
		test: (path) => path === "methods" || /methods.(\d)+.name/.test(path) || /methods.(\d)+$/.test(path)
	}
];
/**
* 数据源更新后需要重建 / 重新收集的依赖类型；没有影响依赖的变化时返回 `null`。
* 按变更记录顺序，取第一条命中规则的记录。
*/
var getDataSourceRecollectTypes = (changeRecords) => {
	for (const { propPath } of changeRecords) {
		if (!propPath) continue;
		const rule = DATA_SOURCE_RECOLLECT_RULES.find(({ test }) => test(propPath));
		if (rule) return rule.types;
	}
	return null;
};
/** 为数据源创建依赖目标（默认三类都建），`reactive` 用于使依赖结果在浏览器端可被订阅 */
var addDataSourceTargets = (dep, ds, reactive, types = DATA_SOURCE_DEP_TYPES) => {
	for (const type of types) dep.addTarget(DATA_SOURCE_TARGET_CREATORS[type](ds, reactive({})));
};
var removeDataSourceTargets = (dep, id, types = DATA_SOURCE_DEP_TYPES) => {
	for (const type of types) dep.removeTarget(id, type);
};
/** root 变化后重建所有依赖目标：代码块 + 数据源 */
var resetDepTargets = (dep, codeBlocks, dataSources, reactive) => {
	dep.clearTargets();
	for (const [id, code] of Object.entries(codeBlocks)) dep.addTarget(createCodeBlockTarget(id, code));
	for (const ds of dataSources) addDataSourceTargets(dep, ds, reactive);
};
/** 依赖目标新增后，把依赖信息写回 root */
var writeTargetDeps = (root, target) => {
	if (!root || !isDataSourceDepType(target.type)) return;
	const key = DEPS_KEY[target.type];
	root[key] = root[key] || {};
	root[key][target.id] = target.deps;
};
/** 依赖目标移除后，从 root 上清掉对应的依赖信息 */
var removeTargetDeps = (root, id, type) => {
	if (!root || !isDataSourceDepType(type)) return;
	delete root[DEPS_KEY[type]]?.[id];
};
//#endregion
export { addDataSourceTargets, classifyUpdatedNodes, getDataSourceRecollectTypes, removeDataSourceTargets, removeTargetDeps, resetDepTargets, writeTargetDeps };
