//#region packages/form/src/utils/actionButton.ts
/** table / group-list 行操作的内置文案。空 text 与未配置一样回退到这里，与 addButtonConfig 一致 */
var DEFAULT_ACTION_BUTTON_TEXT = {
	operate: "操作",
	delete: "删除",
	copy: "复制",
	dropSort: "拖动排序",
	moveUp: "上移",
	moveDown: "下移",
	moveTo: "移动至"
};
var actionButtonText = (config, key) => config?.text || DEFAULT_ACTION_BUTTON_TEXT[key];
//#endregion
export { DEFAULT_ACTION_BUTTON_TEXT, actionButtonText };
